// Block (composition) — searchable, paginated tabular data with an empty fallback.
// Table owns all table-part visuals; this Block only wires collections and arrangement.
import type { ReactNode, Ref } from "react";
import { Pagination } from "../components/Pagination";
import { ScrollArea } from "../components/ScrollArea";
import { SearchField } from "../components/SearchField";
import { Stack } from "../layouts/Stack";
import {
  Table,
  TableBody,
  TableCell,
  TableColumn,
  TableHeader,
  TableRow,
} from "../components/Table";
import { EmptyState } from "./EmptyState";
import "./DataTable.css";

export interface DataTableProps {
  /** Column definitions, in display order. `align: "end"` for a numeric column (an amount, a count). */
  columns: { id: string; label: string; align?: "start" | "end" }[];
  /** Row records keyed by column id. Each row must also include an id. */
  rows: Record<string, ReactNode>[];
  searchValue?: string;
  onSearchChange?: (value: string) => void;
  page?: number;
  totalPages?: number;
  onPageChange?: (page: number) => void;
  emptyLabel?: string;
  /** Optional controls displayed opposite the search field. */
  actions?: ReactNode;
  /** Names the table. Prefer `aria-labelledby` when a visible heading already names it. */
  "aria-label"?: string;
  /** Id of the visible heading that names the table. */
  "aria-labelledby"?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function DataTable({
  columns,
  rows,
  searchValue,
  onSearchChange,
  page = 1,
  totalPages,
  onPageChange,
  emptyLabel = "No results",
  actions,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledby,
  className,
  ref,
}: DataTableProps) {
  return (
    <Stack
      as="section"
      ref={ref}
      gap="medium"
      aria-label="Data table"
      className={className ? `sd-datatable ${className}` : "sd-datatable"}
    >
      <Stack
        direction={{ small: "column", medium: "row" }}
        align={{ small: "stretch", medium: "center" }}
        justify="between"
        gap="small"
        className="sd-datatable__toolbar"
      >
        <SearchField
          aria-label="Search table"
          placeholder="Search"
          value={searchValue}
          onChange={onSearchChange}
          className="sd-datatable__search"
        />
        {actions}
      </Stack>

      {/* A search that empties the table moves no focus, so the empty state below is never heard.
          The live region stays mounted and only its text changes, which is what gets announced
          (WCAG 4.1.3). */}
      <p role="status" className="sd-visually-hidden">
        {searchValue && rows.length === 0 ? emptyLabel : ""}
      </p>

      {/* spacing: attachment — the toolbar searches and acts on the table below it */}
      {rows.length > 0 ? (
        // A `<table>` is `display: table`: it refuses to shrink below its min-content width, and its
        // own `overflow` cannot constrain it — `Table.css`'s `overflow: hidden` clips the border
        // radius and does nothing here. So a Table in any container narrower than its columns spills
        // out SILENTLY: a 427px table in a 300px grid track paints 127px of itself over its neighbour
        // while every box stays inside its own cell, which no sibling-overlap check would catch.
        // The scrollport is the library's existing answer (ScrollArea, same as Carousel's viewport),
        // and it brings the obligation with it: ScrollArea is a tab stop with the token focus ring,
        // so the region stays reachable without a pointer (axe scrollable-region-focusable / 2.1.1).
        <ScrollArea orientation="horizontal" className="sd-datatable__scroll">
        <Table
          aria-label={ariaLabel ?? (ariaLabelledby ? undefined : "Results")}
          aria-labelledby={ariaLabelledby}
        >
          <TableHeader columns={columns}>
            {(column) => (
              <TableColumn id={column.id} align={column.align} isRowHeader={column.id === columns[0]?.id}>
                {column.label}
              </TableColumn>
            )}
          </TableHeader>
          <TableBody items={rows}>
            {(row) => (
              <TableRow id={String(row.id)} columns={columns}>
                {(column) => <TableCell align={column.align}>{row[column.id]}</TableCell>}
              </TableRow>
            )}
          </TableBody>
        </Table>
        </ScrollArea>
      ) : (
        <EmptyState title={emptyLabel} />
      )}

      {/* spacing: attachment — the pagination pages the table above it */}
      {totalPages ? (
        <Pagination
          page={page}
          total={totalPages}
          onPageChange={onPageChange ?? (() => undefined)}
        />
      ) : null}
    </Stack>
  );
}

/* DataTable.css — .sd-datatable (Block)
   Arrangement only. Table and every Table part retain their owned look. */
.sd-datatable {
  width: 100%;
}

.sd-datatable__search {
  width: 100%;
}

@media (min-width: 768px) {
  .sd-datatable__search {
    max-width: 20rem;
  }
}

/* The scrollport must be allowed to be NARROWER than the table it holds. Both halves are needed:
   `min-width: 0` because a flex item defaults to `min-width: auto` and would otherwise grow to the
   table's min-content, and `width: 100%` so it fills the track it is given rather than the content. */
.sd-datatable__scroll {
  min-width: 0;
  width: 100%;
}
